// Generates src/infrastructure/migrations.generated.ts for every package that has drizzle-kit output in drizzle/.
// Run after `drizzle-kit generate` (see the db:generate script). The generated file is committed.
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dir, "..", "packages");
for (const pkg of readdirSync(root)) {
  const journalPath = join(root, pkg, "drizzle", "meta", "_journal.json");
  if (!existsSync(journalPath)) continue;
  const journal = JSON.parse(readFileSync(journalPath, "utf8")) as { entries: { idx: number; tag: string; when: number }[] };
  const imports = journal.entries.map((e) => `import m${e.idx} from "../../drizzle/${e.tag}.sql" with { type: "text" };`);
  const rows = journal.entries.map((e) => `  { tag: ${JSON.stringify(e.tag)}, when: ${e.when}, sql: m${e.idx} },`);
  const out = [
    "// Generated by scripts/embed-migrations.ts from drizzle/meta/_journal.json. Do not edit.",
    'import type { EmbeddedMigration } from "@example/sqlite-support";',
    'import journal from "../../drizzle/meta/_journal.json";',
    ...imports,
    "",
    "export const MIGRATIONS: readonly EmbeddedMigration[] = [",
    ...rows,
    "];",
    "",
    "/** Tags drizzle-kit recorded. Compared with MIGRATIONS at startup and in tests, so a forgotten embed step fails loudly. */",
    "export const JOURNAL_TAGS: readonly string[] = journal.entries.map((e) => e.tag);",
    "",
  ].join("\n");
  writeFileSync(join(root, pkg, "src", "infrastructure", "migrations.generated.ts"), out);
  console.log(`${pkg}: ${journal.entries.length} migration(s) embedded`);
}
